import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.BvlN9b-o.js";const b=JSON.parse('{"title":"Add Observability to Your Business","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/observability","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/observability.md","filePath":"en/tutorials/observability.md"}'),i={name:"en/tutorials/observability.md"};function o(n,e,l,p,c,u){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="add-observability-to-your-business" tabindex="-1">Add Observability to Your Business <a class="header-anchor" href="#add-observability-to-your-business" aria-label="Permalink to &quot;Add Observability to Your Business&quot;">​</a></h1><p>Goal: trace your HTTP request through Jobs, storage and audit without making telemetry a commit dependency. Start with a <a href="./first-request">public API</a>; background work uses <a href="./document-exports">Jobs</a>, durable success uses <a href="./audit-history">Audit</a>.</p><h2 id="start-optional-telemetry-services" tabindex="-1">Start Optional Telemetry Services <a class="header-anchor" href="#start-optional-telemetry-services" aria-label="Permalink to &quot;Start Optional Telemetry Services&quot;">​</a></h2><p>Run from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev-observability</span></span></code></pre></div><p>This starts normal development services plus Collector, Tempo, Loki, Prometheus and Grafana. Open SaaS operations in <a href="http://127.0.0.1:3300" target="_blank" rel="noreferrer">Grafana</a>. Anonymous read-only local access and loopback ports are not production authentication. Normal <code>just dev</code> omits this stack.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/compose.observability.yaml" target="_blank" rel="noreferrer">Compose overlay</a> and <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/deploy/observability/collector.yaml" target="_blank" rel="noreferrer">Collector configuration</a> define actual services/data sources. Configure TELEMETRY_HTTP_PORT/TEMPO_PORT/LOKI_PORT/PROMETHEUS_PORT/GRAFANA_PORT for conflicts. Use <code>just observability-up / observability-validate / observability-down</code> independently; starting Collector does not enable export in existing processes. Restart applications or explicitly configure TELEMETRY_ENDPOINT/TELEMETRY_LOG_DIRECTORY.</p><h2 id="reuse-public-wiring" tabindex="-1">Reuse Public Wiring <a class="header-anchor" href="#reuse-public-wiring" aria-label="Permalink to &quot;Reuse Public Wiring&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/http.rs" target="_blank" rel="noreferrer">HTTP context</a> creates request IDs/spans, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer">Jobs enqueue</a> persists safe parent/correlation/actor, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/jobs/worker.rs" target="_blank" rel="noreferrer">Worker</a> creates an independent attempt span and the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/platform/src/object_storage.rs" target="_blank" rel="noreferrer">storage adapter</a> records finite operations/outcomes. Your Domain need not depend on OTel.</p><p>Responses carry <code>x-request-id / x-trace-id</code> for Tempo/Loki correlation. HTTP spans can end before queued work starts; Worker restores W3C parent from the database. Restart/retry creates fresh spans rather than reusing IDs. traceparent is telemetry only, never authorization. Baggage/tracestate/raw URI/full headers are not persisted.</p><p>Add only necessary static events in your use case; call/field excerpt:</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tracing</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(action </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tickets.export.requested&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;business request accepted&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Record at the actual success point and actor only after authorization. Exclude bodies, tokens, passwords, signed URLs and raw AWS/Redis errors. Keep route/kind/operation/outcome labels finite. User/Job/resource/trace IDs are correlation fields, never metric labels.</p><h2 id="correlate-with-durable-results" tabindex="-1">Correlate with Durable Results <a class="header-anchor" href="#correlate-with-durable-results" aria-label="Permalink to &quot;Correlate with Durable Results&quot;">​</a></h2><p>Replace the example value with your full trace ID:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{service_name=~&quot;saas-api|saas-worker&quot;} |= &quot;YOUR_TRACE_ID&quot;</span></span>
<span class="line"><span>sum by (route, status) (rate(saas_http_requests_total[5m]))</span></span>
<span class="line"><span>sum by (kind, outcome) (rate(saas_jobs_attempts_total[5m]))</span></span></code></pre></div><p>The first line is LogQL, the others PromQL. JSON context lives in span/spans and event fields in fields rather than all at top level. Rates need at least two scrapes; Histogram P95 interpolates buckets. A transient attempt is not terminal Job failure. Compare task batch/history, business result and Audit; an observed span does not prove commit.</p><h2 id="telemetry-failure-cannot-backpressure-business" tabindex="-1">Telemetry Failure Cannot Backpressure Business <a class="header-anchor" href="#telemetry-failure-cannot-backpressure-business" aria-label="Permalink to &quot;Telemetry Failure Cannot Backpressure Business&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/platform/src/telemetry/mod.rs" target="_blank" rel="noreferrer">Platform telemetry</a> defaults to span queue 512, batch 64 and lossy log queue 1024; overflow drops observations. OTLP has a 1-second total budget without automatic retry. Collector has a memory limiter, finite queues and at most 10 seconds retry. Collector failure neither fails database readiness nor reexecutes business.</p><p>Empty TELEMETRY_ENDPOINT disables export; current support is local HTTP loopback/collector service name. Invalid parents start fresh traces; upstream unsampled traces may return IDs without exported records. Output accepts only controlled project saas_* targets, including TRACE level, without enabling third-party secret logs.</p><p>Shutdown drains business first, then closes providers finitely. Trace has 2 seconds, current metrics reader 5 seconds and logs a finite wait; data loss is allowed. Hourly app files retain at most 24 files, not an exact disk quota. Prometheus/Loki retention is asynchronous and development volume capacity needs monitoring. Define production budgets/retention explicitly.</p><h2 id="verify-integration" tabindex="-1">Verify Integration <a class="header-anchor" href="#verify-integration" aria-label="Permalink to &quot;Verify Integration&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telemetry</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telemetry_outage</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telemetry_shutdown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jobs</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/tests/telemetry.rs" target="_blank" rel="noreferrer">Public checks</a> capture real OTLP protobuf and drive HTTP/Worker/storage to verify parents, actors, audit and finite labels. <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/tests/telemetry_outage.rs" target="_blank" rel="noreferrer">Outage</a> and <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/tests/telemetry_shutdown.rs" target="_blank" rel="noreferrer">shutdown</a> prove blocked export still allows business, bounded backlog and exit.</p><p>Provide matching HTTP/job-result and telemetry-query scenarios for your business. Continue with <a href="./single-machine-production">production</a>.</p><p>For telemetry wiring changes, <code>node scripts/knowledge-observability-smoke.mjs</code> queries real Tempo/Loki/Prometheus/Grafana/Audit in isolation and retains safe IDs. This smoke belongs to the Knowledge reference. See <a href="./perf-gates">performance budgets</a> for capacity validation.</p><hr><p>Source version：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/tutorials/19-observability.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,28)])])}const h=a(i,[["render",o]]);export{b as __pageData,h as default};
